<?= $this->extend('layouts/main') ?>
<?= $this->section('content') ?>
<?php $items = $notificationItems ?? []; $filter = $notificationFilter ?? 'all'; ?>
<div class="container-fluid px-0"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><span class="text-uppercase small fw-semibold text-primary">Inbox</span><h3 class="mb-1">Pusat Notifikasi</h3><p class="text-muted mb-0">Semua penugasan dan reminder checklist Anda.</p></div><form method="post" action="<?= base_url('settings/change-password') ?>"><?= csrf_field() ?><input type="hidden" name="settings_action" value="mark_notifications_read"><button class="btn btn-outline-primary"><i class="bi bi-check2-all me-1"></i>Tandai semua dibaca</button></form></div>
<div class="d-flex flex-wrap gap-2 mb-3"><?php foreach (['all'=>'Semua','unread'=>'Belum dibaca','assignment'=>'Penugasan','reminder'=>'Reminder'] as $key=>$label): ?><a class="btn btn-sm <?= $filter === $key ? 'btn-primary' : 'btn-outline-secondary' ?>" href="<?= base_url('home?view=notifications&type=' . $key) ?>"><?= esc($label) ?></a><?php endforeach; ?></div>
<div class="card border-0 shadow-sm"><div class="list-group list-group-flush"><?php if ($items === []): ?><div class="text-center text-muted py-5"><i class="bi bi-bell-slash fs-2 d-block mb-2"></i>Tidak ada notifikasi.</div><?php else: ?><?php foreach ($items as $item): ?><?php $target = base_url(ltrim((string) ($item['url'] ?? 'home'), '/')) . (str_contains((string) ($item['url'] ?? ''), '?') ? '&' : '?') . 'notification_id=' . (int) $item['id']; ?><a href="<?= esc($target) ?>" class="list-group-item list-group-item-action d-flex gap-3 py-3 <?= empty($item['read_at']) ? 'bg-primary-subtle' : '' ?>"><span class="rounded-circle bg-light d-inline-flex align-items-center justify-content-center flex-shrink-0" style="width:42px;height:42px"><i class="bi <?= ($item['type'] ?? '') === 'reminder' ? 'bi-alarm text-warning' : 'bi-person-check text-primary' ?>"></i></span><div class="flex-grow-1"><div class="d-flex justify-content-between gap-2"><strong><?= esc($item['title'] ?? 'Notifikasi') ?></strong><small class="text-muted"><?= esc($item['created_at'] ?? '') ?></small></div><p class="mb-0 text-muted"><?= esc($item['message'] ?? '') ?></p></div><?php if (empty($item['read_at'])): ?><span class="badge bg-primary align-self-center">Baru</span><?php endif; ?></a><?php endforeach; ?><?php endif; ?></div></div></div>
<?= $this->endSection() ?>
